            "text": "Модель №11. Ниже будет выдержка из моей статьи Как вязать носки спицами. Много вариантов. Тогда разные носки никто не носил, а теперь это модно! Поэтому рекомендую! Вяжите, не пытаясь совместить цвета, и у Вас будут самые модные толстые носки! Причём, им сейчас уже 4 года, стирались даже в машинке. И до сих пор целые! Нигде не продырявились!«Пряжа YarnArt EVEREST ( 200 г/ 320 м, 70% акрил, 30% шерсть) из одного мотка вышли эти высокие носки размер 39 и пальто для игрушки кошечка Ли — Ли. Пряжа очень мне понравилась: не линяет, держит форму, теплая, из неё приятно вязать. А вот цвет подобрать, чтобы носки вышли одинаковые, мне не удалось, хотя я честно старалась.»"
