            "text": "Набираем петли из кромочных пятки. В идеале должно получиться такое же количество петель, что и убавили. Если набралось петель больше, это поправимо. В следующих рядах будем убавлять через ряд по одной петле с каждой стороны, пока не получится нужное число петель. Если высокий взъём ноги, тогда обязательно набираем петель больше. Петли можно набирать как лицевые, так и изнаночные. Получится красиво в любом случае, я покажу на фото.из кромочных пятки носка набирались изнаночные петли"
