            "label": "Абзац 17",
            "text": "Из 3 лицевых вывязываем 3 лицевых («звёзды»):3 лицевые петли провязываем вместе лицевой, петлю с левой спицы не скидываем, накид и еще раз из нее же провязываем лицевую петлю. Теперь с левой спицы скинуть петли."
