            "text": "Третий вариант: дополнительную тонкую спицу вводим под все 10 рубчиков. Вязать удобно и за переднюю, и за заднюю стенки. Как нравится. Я иногда набираю ещё дополнительно одиннадцатую петлю (из протяжки предыдущего ряда), чтобы не образовалась дырочка между пяткой и паголенком. Смотрю по ситуации. Дырку обычно видно сразу. Здесь добавила по 1 петле с каждой стороны. Осталось 2 крайние петли подошвы перекинуть на спицы рядом"
