            "label": "Абзац 12",
            "text": "Чтобы удобно было вязать, оставляю средние 6 петель подошвы на отдельной спице. Было 8. По одной петле с каждого края подошвы надо перекинуть к 10 только что набранным петлям. (У меня на фото было не 10, а 11 петель.) И на эти же спицы перекинуть по 1 крайней петле из тех, что остались на спицах (в моём случае их было 32). В итоге 1+10+1=12 петель на спице. На спицах ситуация такая: 6 петель подошвы+12+30+12. Начало ряда посередине пятки. Если у Вас не 40 петель, тогда вместо 30 будет другая цифра. Допустим, у Вас 48 петель, тогда будет 48-(8+2)=38."
