            "id": "n2s6-s42",
            "label": "Абзац 22",
            "text": "На мой 37 размер ноги носки чуть-чуть маловаты. Берите пряжу толще. Например, в 100 г 170 или 200 м. Тогда это описание вам точно подойдёт. Можно связать на пару последних рядов длиннее. И цвета должны быть контрастные."
