            "text": "Стопа, пятка и клин подъёма стопы2. Стопу вязать следующим образом: петли от правой средней петли до левой средней петли равномерно распределить на 1-ю и 2-ю спицы — они образуют верхнюю часть стопы, оставшиеся петли равномерно распределить на 3-ю и 4-ю спицы — они образуют подошву. Далее"
