            "text": "ПЯТКА «БУМЕРАНГ». Пятка «бумеранг» вяжется на п. 1-й и 4-й спиц прямыми и обратными рядами. Если верхняя часть носка вяжется узором, то за 1-2 см до окончания верхней части вязать на п. 1-й и 4-й спиц лиц. гладью, т.к. пятка «бумеранг» короче, чем традиционная пятка, а на п. 2-й и 3-й спиц вязать узором. При необходимости в 1-м круг. р. можно убавить петли на 1-й и 4-й спицах. Разделить петли пятки на три части и вязать укороченными р. от внешней стороны к внутренней на п. обеих внешних частей и на крайних п. средней трети, начиная с крайних петель 1-й или 4-й спиц:"
